    "home_sell_title": "Verkoop je luxestukken.",
    "home_sell_body": "Wij kopen tweedehands en vintage luxekleding, tassen en accessoires. Een eerlijke taxatie en een eenvoudig proces geven de stukken die je niet meer draagt een tweede leven.",
