    "faq_cat_purchase": "Aankopen",
    "faq_q_unique": "Zijn de stukken uniek?",
    "faq_a_unique": "Ja. Elk stuk is uniek: zodra het is verkocht, verdwijnt het uit de collectie en komt het niet terug. Daarom loont het om snel te handelen als je iets vindt waar je van houdt.",
    "faq_q_payment": "Hoe werkt de betaling?",
    "faq_a_payment": "Wanneer je doorgaat, wordt een beveiligde betaallink voor dat stuk geopend. Afhankelijk van de beschikbaarheid kun je betalen met een kaart, digitale portemonnee, in termijnen of met cryptovaluta.",
    "faq_q_prices": "Zijn de prijzen onderhandelbaar?",
    "faq_a_prices": "Nee. We bepalen de prijzen op basis van het model, de staat en de markt. Ze liggen al ruim onder de winkelprijs. Eventuele acties kondigen we aan op Instagram.",
    "faq_cat_auth": "Authenticiteit en staat",
    "faq_q_condition": "Hoe kan ik vertrouwen op de beschrijving van de staat?",
    "faq_a_condition": "Leer en stoffen zijn levende materialen: ze worden soepeler en ontwikkelen na verloop van tijd patina. Patina is geen gebrek; het maakt deel uit van het verhaal. Bij werkelijke schade — een kras of slijtage — fotograferen we die en vermelden we dit in de productdetails.",
    "faq_q_verify": "Wie controleert de stukken?",
    "faq_a_verify": "Elk stuk gaat één voor één door onze handen. Met ondersteuning van IRIS inspecteren we materialen, metalen onderdelen, stiksels en serienummers. Het is geen automatisch keurmerk, maar een praktische controle.",
    "faq_cat_shipping": "Verzending en retourneren",
    "faq_q_shipping": "Hoe verzenden jullie?",
    "faq_a_shipping": "We gebruiken snelle vervoerders met tracking en verzekering in heel Europa. Standaardlevering duurt 3–5 werkdagen en expreslevering 1–2. Je ontvangt een bestelbevestiging en daarna trackingupdates tot aan de bezorging.",
    "faq_q_tracking": "Hoe volg ik mijn bestelling?",
    "faq_a_tracking_before": "Gebruik de code uit de e-mail in het onderdeel",
    "faq_a_tracking_after": "van deze website.",
