    "about_story_quote": "“Ik heb altijd met zorg naar schoonheid gezocht. De zee leerde me haar te herkennen.”",
    "about_story": "Bluèlle is gebouwd op een geoefend oog voor selectie — het vermogen om te onderscheiden wat blijft van wat vervaagt. Elk stuk dat je hier vindt, heb ik persoonlijk gezocht, in handen gehad en beoordeeld. Alleen authenticiteit. Alleen prijzen die kloppen.",
