    "home_payment_closing": "<span>Karty, portfele cyfrowe i raty.</span><span>Więcej opcji dostępnych przy finalizacji zamówienia.</span>",
    "home_sell_aria": "Sprzedaj swoje rzeczy",
    "home_sell_eye": "Usługa",
    "home_sell_title": "Sprzedaj swoje luksusowe rzeczy.",
    "home_sell_body": "Kupujemy używaną i vintage odzież luksusową, torebki oraz akcesoria. Uczciwa wycena i prosty proces dają drugie życie rzeczom, których już nie nosisz.",
