    "faq_eye": "Pomoc",
    "faq_title": "Jak możemy pomóc?",
    "faq_quick_tracking": "Śledź zamówienie",
    "faq_quick_collection": "Kolekcja",
    "faq_quick_auth": "Autentyczność",
    "faq_quick_sell": "Sprzedaj nam",
    "faq_cat_purchase": "Zakupy",
    "faq_q_unique": "Czy każda rzecz jest jedyna w swoim rodzaju?",
    "faq_a_unique": "Tak. Każda rzecz występuje w jednym egzemplarzu: po sprzedaży znika z kolekcji i już nie wraca. Dlatego warto działać szybko, gdy znajdziesz coś, co pokochasz.",
    "faq_q_payment": "Jak działa płatność?",
    "faq_a_payment": "Po przejściu dalej otworzy się bezpieczny link płatniczy przypisany do danej rzeczy. W zależności od dostępności możesz zapłacić kartą, portfelem cyfrowym, w ratach lub kryptowalutą.",
    "faq_q_prices": "Czy ceny podlegają negocjacji?",
    "faq_a_prices": "Nie. Ustalamy ceny na podstawie modelu, stanu i rynku; są one już znacznie niższe od cen detalicznych. Ewentualne promocje ogłaszamy w serwisie Instagram.",
    "faq_cat_auth": "Autentyczność i stan",
    "faq_q_condition": "Skąd mam wiedzieć, że opis stanu jest wiarygodny?",
    "faq_a_condition": "Skóra i tkaniny to żywe materiały: z czasem miękną i nabierają patyny. Patyna nie jest wadą — stanowi część historii. Jeśli występuje rzeczywiste uszkodzenie, takie jak rysa lub przetarcie, fotografujemy je i opisujemy w szczegółach produktu.",
    "faq_q_verify": "Kto weryfikuje rzeczy?",
    "faq_a_verify": "Każda rzecz przechodzi przez nasze ręce, jedna po drugiej. Z pomocą IRIS sprawdzamy materiały, okucia, szwy i numery seryjne. Nie jest to automatyczna odznaka, lecz dokładna kontrola ręczna.",
    "faq_cat_shipping": "Wysyłka i zwroty",
    "faq_q_shipping": "Jak realizujecie wysyłkę?",
    "faq_a_shipping": "Korzystamy ze śledzonych i ubezpieczonych przesyłek ekspresowych w całej Europie. Dostawa standardowa trwa 3–5 dni roboczych, a ekspresowa 1–2 dni. Otrzymasz potwierdzenie zamówienia, a następnie aktualizacje śledzenia aż do doręczenia.",
    "faq_q_tracking": "Jak śledzić zamówienie?",
    "faq_a_tracking_before": "Użyj kodu przesłanego e-mailem w sekcji",
    "faq_a_tracking_after": "tej witryny.",
    "faq_q_missing": "Nie mogę znaleźć odpowiedzi na swoje pytanie.",
    "faq_a_missing": "Napisz do nas. Odpowiadamy osobiście, zwykle w ciągu kilku godzin. Użyj WhatsApp do szybkich pytań, a e-maila do pozostałych spraw.",
    "faq_contact_title": "Porozmawiaj z nami",
