    "about_story_quote": "“Zawsze uważnie szukam piękna. Morze nauczyło mnie je rozpoznawać.”",
    "about_story": "Bluèlle powstało z wyćwiczonego oka do selekcji — umiejętności odróżniania tego, co trwałe, od tego, co przemija. Każda rzecz, którą tu znajdziesz, została przeze mnie osobiście wyszukana, obejrzana i oceniona. Tylko autentyczność. Tylko rozsądne ceny.",
