    "faq_cat_purchase": "Cumpărături",
    "faq_q_unique": "Piesele sunt unicat?",
    "faq_a_unique": "Da. Fiecare piesă este un articol unic: după ce se vinde, părăsește colecția și nu mai revine. De aceea merită să acționezi rapid când găsești ceva ce îți place.",
    "faq_q_payment": "Cum funcționează plata?",
    "faq_a_payment": "Când continui, se deschide un link de plată securizat dedicat acelei piese. În funcție de disponibilitate, poți plăti cu cardul, un portofel digital, în rate sau cu criptomonedă.",
    "faq_q_prices": "Prețurile sunt negociabile?",
    "faq_a_prices": "Nu. Stabilim prețurile în funcție de model, stare și piață, iar acestea sunt deja mult sub prețul de retail. Anunțăm eventualele promoții pe Instagram.",
