    "faq_q_condition": "Cum pot avea încredere în raportul privind starea?",
    "faq_a_condition": "Pielea și țesăturile sunt materiale vii: se înmoaie și dezvoltă o patină în timp. Patina nu este un defect, ci face parte din poveste. Când există o deteriorare reală — o zgârietură sau uzură — o fotografiem și o menționăm în detaliile produsului.",
    "faq_q_verify": "Cine verifică piesele?",
    "faq_a_verify": "Fiecare piesă trece prin mâinile noastre, una câte una. Inspectăm materialele, accesoriile metalice, cusăturile și numerele de serie cu sprijinul IRIS. Nu este o etichetă automată, ci o verificare practică.",
