    "about_story": "Bluèlle se bazează pe un ochi format pentru selecție — capacitatea de a deosebi ceea ce rezistă de ceea ce se estompează. Fiecare piesă pe care o găsești aici a fost căutată, examinată și evaluată personal de mine. Doar autenticitate. Doar prețuri care au sens.",
