    "faq_q_unique": "Finns varje plagg bara i ett exemplar?",
    "faq_a_unique": "Ja. Varje plagg är unikt: när det säljs lämnar det kollektionen och kommer inte tillbaka. Därför kan det vara klokt att agera snabbt när du hittar något du tycker om.",
    "faq_q_payment": "Hur fungerar betalningen?",
    "faq_a_payment": "När du fortsätter öppnas en säker betalningslänk som är reserverad för just det plagget. Beroende på tillgänglighet kan du betala med kort, digital plånbok, delbetalning eller kryptovaluta.",
    "faq_q_prices": "Går det att förhandla om priserna?",
    "faq_a_prices": "Nej. Vi sätter priserna utifrån modell, skick och marknad, och de ligger redan klart under ordinarie butikspris. Eventuella kampanjer annonserar vi på Instagram.",
    "faq_cat_auth": "Äkthet och skick",
    "faq_q_condition": "Hur kan jag lita på skickbeskrivningen?",
    "faq_a_condition": "Läder och textilier är levande material: de mjuknar och utvecklar patina med tiden. Patina är inget fel, utan en del av plaggets historia. När det finns en faktisk skada — en repa eller slitage — fotograferar vi den och redovisar den i produktinformationen.",
    "faq_q_verify": "Vem verifierar plaggen?",
    "faq_a_verify": "Varje plagg passerar våra händer, ett i taget. Med stöd av IRIS granskar vi material, metalldetaljer, sömmar och serienummer. Det är ingen automatisk märkning, utan en omsorgsfull manuell granskning.",
    "faq_cat_shipping": "Leverans och returer",
    "faq_q_shipping": "Hur skickar ni?",
    "faq_a_shipping": "Vi använder spårbara och försäkrade expressbud i hela Europa. Standardleverans tar 3–5 arbetsdagar och express 1–2 dagar. Du får först en orderbekräftelse och därefter spårningsuppdateringar fram till leverans.",
    "faq_q_tracking": "Hur spårar jag min beställning?",
    "faq_a_tracking_before": "Använd koden som skickades via e-post i",
    "faq_a_tracking_after": "på den här webbplatsen.",
