    "faq_q_unique": "Finnes hvert plagg bare i ett eksemplar?",
    "faq_a_unique": "Ja. Hvert plagg er unikt: Når det er solgt, forlater det kolleksjonen og kommer ikke tilbake. Derfor kan det lønne seg å handle raskt når du finner noe du liker.",
    "faq_q_payment": "Hvordan fungerer betalingen?",
    "faq_a_payment": "Når du fortsetter, åpnes en sikker betalingslenke som er reservert for akkurat det plagget. Avhengig av tilgjengelighet kan du betale med kort, digital lommebok, delbetaling eller kryptovaluta.",
    "faq_q_prices": "Kan prisene forhandles?",
    "faq_a_prices": "Nei. Vi setter prisene ut fra modell, tilstand og marked, og de ligger allerede godt under ordinær butikkpris. Eventuelle kampanjer kunngjør vi på Instagram.",
    "faq_cat_auth": "Ekthet og tilstand",
    "faq_q_condition": "Hvordan kan jeg stole på tilstandsrapporten?",
    "faq_a_condition": "Skinn og tekstiler er levende materialer: De mykner og utvikler patina over tid. Patina er ikke en feil, men en del av plaggets historie. Når det finnes en faktisk skade — en ripe eller slitasje — fotograferer vi den og opplyser tydelig om den i produktdetaljene.",
    "faq_q_verify": "Hvem verifiserer plaggene?",
    "faq_a_verify": "Hvert plagg går gjennom hendene våre, ett om gangen. Med støtte fra IRIS kontrollerer vi materialer, metalldetaljer, sømmer og serienumre. Det er ikke et automatisk merke, men en grundig manuell kontroll.",
