    "faq_a_shipping": "Vi bruker sporbare og forsikrede ekspressbud i hele Europa. Standard levering tar 3–5 virkedager og ekspress 1–2 dager. Du mottar først en ordrebekreftelse og deretter sporingsoppdateringer frem til levering.",
