    "home_sell_eye": "Service",
    "home_sell_title": "Sælg dine luksusvarer.",
    "home_sell_body": "Vi køber brugt og vintage luksustøj, tasker og tilbehør. En fair vurdering og en enkel proces giver de varer, du ikke længere bruger, et nyt liv.",
    "home_sell_cta": "Kontakt os på WhatsApp",
