    "faq_quick_auth": "Ægthed",
    "faq_quick_sell": "Sælg til os",
    "faq_cat_purchase": "Køb",
    "faq_q_unique": "Er varerne unikke?",
    "faq_a_unique": "Ja. Hver vare findes kun i ét eksemplar: Når den er solgt, forlader den kollektionen og kommer ikke tilbage. Derfor kan det betale sig at handle hurtigt, når du finder noget, du er vild med.",
    "faq_q_payment": "Hvordan fungerer betalingen?",
    "faq_a_payment": "Når du fortsætter, åbnes et sikkert betalingslink til den pågældende vare. Afhængigt af tilgængeligheden kan du betale med kort, digital tegnebog, afdrag eller kryptovaluta.",
    "faq_q_prices": "Kan priserne forhandles?",
    "faq_a_prices": "Nej. Vi fastsætter priserne ud fra model, stand og marked, og de ligger allerede langt under detailprisen. Eventuelle kampagner annoncerer vi på Instagram.",
    "faq_cat_auth": "Ægthed og stand",
    "faq_q_condition": "Hvordan kan jeg stole på standbeskrivelsen?",
    "faq_a_condition": "Læder og tekstiler er levende materialer: De bliver blødere og udvikler patina med tiden. Patina er ikke en fejl, men en del af historien. Hvis der er en reel skade — en ridse eller slitage — fotograferer vi den og oplyser om den i produktdetaljerne.",
    "faq_q_verify": "Hvem kontrollerer varerne?",
    "faq_a_verify": "Hver vare går gennem vores hænder, én for én. Med hjælp fra IRIS undersøger vi materialer, beslag, syninger og serienumre. Det er ikke et automatisk mærke, men en praktisk kontrol.",
    "faq_cat_shipping": "Forsendelse og retur",
    "faq_q_shipping": "Hvordan sender I?",
    "faq_a_shipping": "Vi bruger ekspresfragt med sporing og forsikring i hele Europa. Standardlevering tager 3–5 hverdage og ekspreslevering 1–2. Du modtager en ordrebekræftelse efterfulgt af sporingsopdateringer frem til levering.",
    "faq_q_tracking": "Hvordan sporer jeg min ordre?",
    "faq_a_tracking_before": "Brug koden, du har modtaget via e-mail, i sektionen",
    "faq_a_tracking_after": "på dette websted.",
    "faq_q_missing": "Jeg kan ikke finde svaret på mit spørgsmål.",
    "faq_a_missing": "Skriv til os. Vi svarer personligt, som regel inden for få timer. Brug WhatsApp til hurtige spørgsmål og e-mail til alt andet.",
    "faq_contact_title": "Tal med os",
    "faq_contact_hours": "Mandag – fredag, kl. 9.00–18.00 (CET)",
