    "home_sell_title": "Lüks parçalarınızı satın.",
    "home_sell_body": "İkinci el ve vintage lüks giyim, çanta ve aksesuarları satın alıyoruz. Adil değerleme ve kolay bir süreçle artık kullanmadığınız parçalara ikinci bir hayat kazandırıyoruz.",
