    "faq_quick_auth": "Orijinallik",
    "faq_quick_sell": "Bize satın",
    "faq_cat_purchase": "Satın alma",
    "faq_q_unique": "Parçaların her biri eşsiz mi?",
    "faq_a_unique": "Evet. Her parçadan yalnızca bir adet bulunur; satıldığında koleksiyondan çıkar ve geri gelmez. Bu nedenle sevdiğiniz bir parça bulduğunuzda hızlı davranmanızda fayda var.",
    "faq_q_payment": "Ödeme nasıl yapılır?",
    "faq_a_payment": "Devam ettiğinizde, o parçaya özel güvenli ödeme bağlantısı açılır. Kullanılabilirliğe bağlı olarak kart, dijital cüzdan, taksit veya kripto para ile ödeme yapabilirsiniz.",
    "faq_q_prices": "Fiyatlarda pazarlık yapılabilir mi?",
    "faq_a_prices": "Hayır. Fiyatları model, durum ve piyasa koşullarına göre belirliyoruz; bu fiyatlar zaten mağaza fiyatlarının oldukça altında. Kampanyaları Instagram üzerinden duyuruyoruz.",
    "faq_cat_auth": "Orijinallik ve durum",
    "faq_q_condition": "Durum raporuna nasıl güvenebilirim?",
    "faq_a_condition": "Deri ve kumaşlar yaşayan malzemelerdir; zamanla yumuşar ve patina kazanır. Patina bir kusur değil, parçanın hikâyesinin bir parçasıdır. Çizik veya aşınma gibi gerçek bir hasar varsa fotoğrafını çeker ve ürün detaylarında açıkça belirtiriz.",
    "faq_q_verify": "Parçaları kim doğruluyor?",
    "faq_a_verify": "Her parça tek tek elimizden geçer. Malzemeleri, metal aksamı, dikişleri ve seri numaralarını IRIS desteğiyle inceleriz. Bu otomatik verilen bir rozet değil, uygulamalı ve titiz bir kontroldür.",
