    "faq_q_shipping": "Nasıl gönderim yapıyorsunuz?",
    "faq_a_shipping": "Avrupa genelinde takipli ve sigortalı ekspres kargo firmalarıyla çalışıyoruz. Standart teslimat 3–5 iş günü, ekspres teslimat ise 1–2 gün sürer. Sipariş onayından teslimata kadar takip güncellemelerini alırsınız.",
    "faq_q_tracking": "Siparişimi nasıl takip ederim?",
