    "faq_q_unique": "每件单品都是独一无二的吗？",
    "faq_a_unique": "是的。每件单品都仅有一件：售出后便会从精选系列中下架，不再补货。因此，遇到心仪之选时不妨尽快入手。",
    "faq_q_payment": "如何付款？",
    "faq_a_payment": "继续购买后，系统会打开该单品专属的安全支付链接。视可用情况，您可使用银行卡、电子钱包、分期付款或加密货币支付。",
    "faq_q_prices": "价格可以协商吗？",
    "faq_a_prices": "不可以。我们的定价综合考虑款式、成色与市场行情，且已显著低于专柜价。如有促销，我们会在 Instagram 上公布。",
    "faq_cat_auth": "正品与成色",
    "faq_q_condition": "如何相信商品成色说明？",
    "faq_a_condition": "皮革与织物会随时间变得柔软并形成自然包浆。包浆并非瑕疵，而是单品故事的一部分。如有实际损伤 — 例如划痕或磨损 — 我们会拍照并在商品详情中如实说明。",
    "faq_q_verify": "由谁鉴定这些单品？",
    "faq_a_verify": "每件单品都由我们亲手逐件检查。借助 IRIS，我们会核验材质、五金、车线与序列号。这不是自动生成的标签，而是真正的人工审查。",
    "faq_cat_shipping": "配送与退货",
    "faq_q_shipping": "如何配送？",
    "faq_a_shipping": "我们在欧洲全境使用可追踪、含保险的快递服务。标准配送需 3–5 个工作日，加急配送需 1–2 个工作日。您将先收到订单确认，随后持续收到物流更新，直至送达。",
