    "faq_q_unique": "すべて一点ものですか？",
    "faq_a_unique": "はい。すべて一品限りです。売れたアイテムはコレクションから姿を消し、再入荷することはありません。心惹かれる一点に出会ったら、ぜひお早めにご検討ください。",
    "faq_q_payment": "支払いはどのように行いますか？",
    "faq_a_payment": "購入手続きへ進むと、その商品専用の安全な決済リンクが開きます。ご利用状況に応じて、カード、ウォレット、分割払い、暗号資産でお支払いいただけます。",
    "faq_q_prices": "価格交渉はできますか？",
    "faq_a_prices": "いいえ。モデル、コンディション、市場相場をもとに価格を設定しており、すでに定価を大きく下回る価格です。キャンペーンを行う場合はInstagramでお知らせします。",
