    "faq_q_condition": "コンディションレポートは信頼できますか？",
    "faq_a_condition": "レザーや生地は、使うほどに柔らかくなり、時とともに風合いを深める素材です。その風合いは欠点ではなく、アイテムが歩んだ物語の一部です。傷や摩耗など実際のダメージがある場合は、写真を掲載し、商品詳細に明記します。",
    "faq_q_verify": "誰が真贋を確認しますか？",
    "faq_a_verify": "すべてのアイテムを一点ずつ実際に手に取り、素材、金具、ステッチ、シリアル番号をIRISのサポートとともに確認します。自動で付与される認証ではなく、人の目と手による検品です。",
