    "faq_cat_purchase": "구매",
    "faq_q_unique": "모든 아이템이 하나뿐인가요?",
    "faq_a_unique": "네. 각 아이템은 단 하나만 입고됩니다. 판매가 완료되면 컬렉션에서 사라지며 재입고되지 않습니다. 마음에 드는 상품을 발견했다면 빠르게 결정하시기를 권해드립니다.",
