    "faq_q_condition": "상품 상태 설명을 믿을 수 있나요?",
    "faq_a_condition": "가죽과 원단은 시간이 흐르며 부드러워지고 파티나가 생기는 살아 있는 소재입니다. 파티나는 결함이 아니라 아이템이 지닌 이야기의 일부입니다. 긁힘이나 마모처럼 실제 손상이 있는 경우 사진으로 기록하고 상품 상세 정보에 명확히 안내합니다.",
    "faq_q_verify": "누가 아이템을 감정하나요?",
    "faq_a_verify": "모든 아이템은 하나씩 직접 손으로 검수합니다. IRIS의 지원을 받아 소재, 하드웨어, 스티치 및 시리얼 번호를 확인합니다. 자동으로 부여되는 배지가 아니라 실제 수작업 검토 과정입니다.",
