    "faq_cat_purchase": "Покупка",
    "faq_q_unique": "Все вещи представлены в единственном экземпляре?",
    "faq_a_unique": "Да. Каждая вещь существует в одном экземпляре: после продажи она покидает коллекцию и больше не возвращается. Поэтому, если вам что-то особенно понравилось, лучше не откладывать решение.",
    "faq_q_payment": "Как проходит оплата?",
    "faq_a_payment": "При переходе к оформлению откроется безопасная платёжная ссылка, созданная специально для этой вещи. В зависимости от доступности можно оплатить картой, электронным кошельком, в рассрочку или криптовалютой.",
