    "faq_a_condition": "Кожа и ткани — живые материалы: со временем они становятся мягче и приобретают благородную патину. Патина не является недостатком — это часть истории вещи. Если есть реальное повреждение, например царапина или потёртость, мы фотографируем его и указываем в описании товара.",
